package dev.cazajefes;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
import org.bukkit.Material;
public class JailCollectionTest {
 @Test public void actualCanonicalCatalogueHasTwentyEightInEachRequestedSection(){for(var group:List.of(RareCompatibility.Group.ARMOR,RareCompatibility.Group.MELEE)){var ids=RareCollections.ids().stream().filter(id->!id.equals("despertar")&&RareCompatibility.property(id)==group).toList();assertEquals(group.title,28,ids.size());assertEquals(28,new HashSet<>(ids).size());}assertEquals(28,JailRareCatalog.ALL.size());}
 @Test public void previousBowAndCrossbowCollectionsRemainTenEach(){for(var group:List.of(RareCompatibility.Group.BOW,RareCompatibility.Group.CROSSBOW))assertEquals(10,RareCollections.ids().stream().filter(id->RareCompatibility.recipeInGroup("crear_esencia_rare_"+id,group)).count());}
 @Test public void everyNewPowerHasShortEffectTagThreeLevelsAndExactRecipe(){for(var spec:JailRareCatalog.ALL){assertTrue(spec.title(),spec.title().contains(" (")&&spec.title().endsWith(")")&&spec.title().substring(spec.title().lastIndexOf('(')+1,spec.title().length()-1).matches("[A-Za-z]+"));var definition=RareDefinitions.get(spec.id());assertNotNull(definition);assertEquals(3,definition.maximum());assertEquals(9,definition.ingredients().size());assertEquals(Material.AIR,definition.ingredients().get(4));assertTrue(RangedRareCatalog.MATERIALS.contains(spec.material()));assertTrue(spec.cooldown()>=8);assertFalse(RecipeAlchemy.usesLegacyProfile("crear_esencia_rare_"+spec.id(),false));assertFalse(spec.description().isBlank());}}
 @Test public void armorCannotBeAppliedToWeaponsAndWeaponsCannotBeAppliedToArmor(){for(var spec:JailRareCatalog.ALL){boolean armor=spec.group()==RareCompatibility.Group.ARMOR;assertEquals(armor,RareCompatibility.accepts(spec.id(),Material.NETHERITE_CHESTPLATE));assertEquals(!armor,RareCompatibility.accepts(spec.id(),Material.NETHERITE_SWORD));assertEquals(!armor,RareCompatibility.accepts(spec.id(),Material.NETHERITE_AXE));assertFalse(RareCompatibility.accepts(spec.id(),Material.BOW));}}
 @Test public void procAndDamageCapsPreventUnlimitedArmorStacking(){assertEquals(.25,JailRareCatalog.chance(1),.00001);assertEquals(.45,JailRareCatalog.chance(3),.00001);assertEquals(.45,JailRareCatalog.chance(99),.00001);assertEquals(1.5,JailRareCatalog.outgoingCap(9),0);assertEquals(.5,JailRareCatalog.defensiveCap(.1),0);assertTrue(JailRares.low(6,20));assertFalse(JailRares.low(8,20));assertFalse(JailRares.low(0,0));}
 @Test public void shiftedBackStarDoesNotCollideWithArmorSealOrCollection(){assertEquals(50,RecipePresentation.LIST_BACK);assertEquals(51,RecipePresentation.ARMOR_LIST_SEAL);for(int slot:RareMenuStyle.slots(28)){assertNotEquals(RecipePresentation.LIST_BACK,slot);assertNotEquals(RecipePresentation.ARMOR_LIST_SEAL,slot);}}
}
